    @Override public void onCreate(Bundle state){super.onCreate(state);db=LibraryDb.get(this);SampleContent.ensure(this);db.scanRoots();scanner=new FolderScanner(this);getWindow().setStatusBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);buildShell();showHome();bindService(new Intent(this,PlayerService.class),connection,BIND_AUTO_CREATE);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},5);ui.post(refresh);}
