    private void refreshPlayerFields(){if(!bound||service.current()==null||playerTitle==null)return;LibraryDb.Track t=db.track(service.current().uri);if(t==null)t=service.current();playerEpisode.setText(episodeLabel(t.name));playerTitle.setText(t.displayTitle());LibraryDb.Folder f=db.folder(t.folderId);playerSubtitle.setText((f==null?"本地音频":f.name)+" · 顺序播放");long pos=service.position(),dur=service.duration();elapsed.setText(format(pos));total.setText(format(dur));seek.setProgress(dur>0?(int)(pos*1000/dur):0);playButton.setText(service.isPlaying()?"Ⅱ\n暂停":"▶\n播放");speedButton.setText(trimSpeed(service.speed())+"×\n倍速");skipButton.setText("片头片尾\n"+(service.introSkip()/1000)+" / "+(service.outroSkip()/1000)+"秒");long rem=service.sleepRemaining();sleepButton.setText(rem>0?"◴\n"+((rem+59999)/60000)+"分":service.sleepAfterTrackEnabled()?"◴\n本集后":"◴\n定时");}
    private String episodeLabel(String name){Matcher m=Pattern.compile("(?<!\\d)(\\d{1,6})(?!\\d)").matcher(name==null?"":name);if(!m.find())return "当前集";try{return "第 "+Long.parseLong(m.group(1))+" 集";}catch(Exception ignored){return "第 "+m.group(1)+" 集";}}
    private void speedDialog(){String[] values={"0.5×","0.75×","1.0×","1.25×","1.5×","1.75×","2.0×","2.5×","3.0×","自定义"};new AlertDialog.Builder(this).setTitle("播放速度（按合集记忆）").setItems(values,(d,w)->{if(w<9)service.setSpeed(Float.parseFloat(values[w].replace("×","")));else customSpeed();refreshPlayerFields();}).show();}
    private void customSpeed(){final EditText e=new EditText(this);e.setInputType(2|8192);e.setHint("0.5 到 3.0");new AlertDialog.Builder(this).setTitle("自定义倍速").setView(e).setPositiveButton("确定",(d,w)->{try{float x=Float.parseFloat(e.getText().toString());service.setSpeed(Math.max(.5f,Math.min(3f,x)));}catch(Exception ignored){}}).setNegativeButton("取消",null).show();}
    private void skipDialog(){LinearLayout form=column(0);form.setPadding(dp(24),0,dp(24),0);form.addView(label("片头跳过秒数（每集开始时跳过）",14,INK,true));EditText intro=new EditText(this);intro.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);intro.setText(String.valueOf(service.introSkip()/1000));form.addView(intro);form.addView(label("片尾跳过秒数（剩余这些秒时播放下一集）",14,INK,true));EditText outro=new EditText(this);outro.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);outro.setText(String.valueOf(service.outroSkip()/1000));form.addView(outro);form.addView(label("填 0 可关闭，最大 600 秒。设置按总合集分别保存；过短的音频不会强制跳过。",12,MUTED,false));new AlertDialog.Builder(this).setTitle("跳过片头和片尾").setView(form).setPositiveButton("保存",(d,w)->{long a=parseSkipSeconds(intro),b=parseSkipSeconds(outro);service.setSkipTimes(a*1000,b*1000);refreshPlayerFields();Toast.makeText(this,"已保存：片头 "+a+" 秒，片尾 "+b+" 秒",Toast.LENGTH_SHORT).show();}).setNegativeButton("取消",null).show();}
    private long parseSkipSeconds(EditText input){try{return Math.max(0,Math.min(600,Long.parseLong(input.getText().toString().trim())));}catch(Exception ignored){return 0;}}
    private void sleepDialog(){String[] x={"10 分钟","20 分钟","30 分钟","60 分钟","当前音频结束","关闭定时"};new AlertDialog.Builder(this).setTitle("睡眠定时").setItems(x,(d,w)->{if(w<4){long[]m={10,20,30,60};service.sleepIn(m[w]*60000);}else if(w==4)service.sleepAfterTrack();else service.sleepIn(0);refreshPlayerFields();}).show();}
    private void bookmarkDialog(){LibraryDb.Track t=service.current();if(t==null)return;EditText note=new EditText(this);note.setHint("备注（可选）");new AlertDialog.Builder(this).setTitle("在 "+format(service.position())+" 添加书签").setView(note).setPositiveButton("保存",(d,w)->{db.addBookmark(t.uri,service.position(),note.getText().toString());Toast.makeText(this,"书签已保存",Toast.LENGTH_SHORT).show();}).setNeutralButton("查看书签",(d,w)->showBookmarks(t)).setNegativeButton("取消",null).show();}
    private void showBookmarks(LibraryDb.Track t){List<String[]> b=db.bookmarks(t.uri);if(b.isEmpty()){Toast.makeText(this,"这段音频还没有书签",Toast.LENGTH_SHORT).show();return;}String[] items=new String[b.size()];for(int i=0;i<b.size();i++)items[i]=format(Long.parseLong(b.get(i)[1]))+(b.get(i)[2].isEmpty()?"":"  ·  "+b.get(i)[2]);new AlertDialog.Builder(this).setTitle("书签").setItems(items,(d,w)->service.seekTo(Long.parseLong(b.get(w)[1]))).show();}

    private void refreshMini(){if(!bound||service.current()==null){if(mini!=null)mini.setVisibility(View.GONE);return;}mini.setVisibility(View.VISIBLE);LibraryDb.Track t=service.current();miniTitle.setText(t.displayTitle());miniState.setText((service.isPlaying()?"播放中 · ":"已暂停 · ")+format(service.position())+" / "+format(service.duration()));long d=service.duration();miniProgress.setProgress(d>0?(int)(service.position()*1000/d):0);View b=mini.findViewWithTag("miniPlay");if(b instanceof TextView)((TextView)b).setText(service.isPlaying()?"暂停":"播放");}
    private void pickFolder(){openFolderPicker(DocumentsContract.buildRootUri("com.android.externalstorage.documents","primary"));}
    private void openFolderPicker(Uri initialUri){if(scanning){Toast.makeText(this,"当前扫描尚未完成，请稍候再添加",Toast.LENGTH_SHORT).show();return;}if(pickingFolder)return;pickingFolder=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,initialUri);try{startActivityForResult(i,PICK_TREE);}catch(Exception e){pickingFolder=false;Toast.makeText(this,"无法打开系统文件夹选择器",Toast.LENGTH_LONG).show();}}
    private String coveringRoot(String authority,String selectedId){try{for(String[]root:db.roots()){if(root[0].startsWith("internal://"))continue;Uri rootUri=Uri.parse(root[0]);if(!Objects.equals(authority,rootUri.getAuthority()))continue;String rootId=DocumentsContract.getTreeDocumentId(rootUri);if(FolderIdentity.isSameOrDescendant(rootId,selectedId))return root[0];}}catch(Exception ignored){}return null;}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=PICK_TREE)return;pickingFolder=false;if(result!=RESULT_OK||data==null||scanning)return;Uri uri=data.getData();if(uri==null)return;String startId,name;try{startId=DocumentsContract.getTreeDocumentId(uri);name=folderDisplayName(uri);}catch(Exception e){Toast.makeText(this,"无法识别所选文件夹",Toast.LENGTH_LONG).show();return;}new FolderBrowserDialog(this,uri,startId,name,new FolderBrowserDialog.Listener(){public void onSelected(String documentId,String selectedName,String path){addSelectedFolder(uri,data,documentId,selectedName,path);}public void onCancelled(){showHome();}}).show();}
    private void addSelectedFolder(Uri pickerUri,Intent grantData,String documentId,String name,String path){if(scanning)return;String permissionUri=coveringRoot(pickerUri.getAuthority(),documentId);if(permissionUri==null){permissionUri=pickerUri.toString();try{if((grantData.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)==0)throw new SecurityException("没有读取授权");getContentResolver().takePersistableUriPermission(pickerUri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception e){Toast.makeText(this,"无法保存文件夹长期读取权限",Toast.LENGTH_LONG).show();return;}db.upsertRoot(permissionUri,folderDisplayName(pickerUri));}db.restoreExcludedDocument(documentId);if(db.coveringScanRoot(permissionUri,documentId)==null)db.upsertScanRoot(permissionUri,documentId,name,path);LibraryDb.Folder folder=new LibraryDb.Folder();folder.id=permissionUri+"#"+documentId;folder.rootUri=permissionUri;folder.parentId=null;folder.name=name;folder.path=path;beginScan();scanner.scanFolder(folder,scanCallback());}
    private String folderDisplayName(Uri uri){String id=DocumentsContract.getTreeDocumentId(uri);int p=id.lastIndexOf(':');String n=p>=0?id.substring(p+1):id;if(n.isEmpty())n="存储空间";int slash=n.lastIndexOf('/');return slash>=0?n.substring(slash+1):n;}
    private FolderScanner.Callback scanCallback(){return new FolderScanner.Callback(){public void onProgress(String t){}public void onDone(int f,int t){scanning=false;if(isFinishing()||isDestroyed())return;Toast.makeText(MainActivity.this,"扫描完成："+t+" 个音频，"+f+" 个文件夹",Toast.LENGTH_LONG).show();showHome();}public void onError(String m){scanning=false;if(isFinishing()||isDestroyed())return;Toast.makeText(MainActivity.this,"扫描失败："+m,Toast.LENGTH_LONG).show();showHome();}};}
    private void beginScan(){scanning=true;if(!isFinishing())showHome();Toast.makeText(this,"开始扫描，请稍候",Toast.LENGTH_SHORT).show();}
    private void rescan(){if(scanning){Toast.makeText(this,"当前扫描尚未完成",Toast.LENGTH_SHORT).show();return;}if(db.scanRoots().isEmpty()){pickFolder();return;}beginScan();scanner.scanAll(scanCallback());}

